(* individual for substantial presence test, days present in current year and prior two years *)
type individual = {
  current_year_days : int;
  first_preceding_year_days : int;
  second_preceding_year_days : int;
}

(* 7701(b)(3)(A)(i) - present at least 31 days in current year *)
let is_present_31_days (person : individual) : bool =
  person.current_year_days >= 31

(* 7701(b)(3)(A)(ii) - weighted sum of days: current year x1, 1st preceding x1/3, 2nd preceding x1/6 *)
let weighted_day_count (person : individual) : float =
  (float_of_int person.current_year_days *. 1.0) +.
  (float_of_int person.first_preceding_year_days *. (1.0 /. 3.0)) +.
  (float_of_int person.second_preceding_year_days *. (1.0 /. 6.0))

let meets_weighted_day_threshold (person : individual) : bool =
  weighted_day_count person >=. 183.0

(* 7701(b)(3)(A) - substantial presence test: both (i) and (ii) must hold *)
let meets_substantial_presence_test (person : individual) : bool =
  is_present_31_days person && meets_weighted_day_threshold person
